service.method:

SELECT
		  USER_ID
		, MENU_PROFILE_CODE
		, USER_TYPE
FROM
	SUSMT
WHERE
	HOUSE_CODE 		    = ${session.HOUSE_CODE}
	AND COMPANY_CODE 	= ${session.COMPANY_CODE}	
	AND USER_ID 		= ${USER_ID}


UPDATE SUSMT
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, USER_NAME_LOC	 	= ${USER_NAME_LOC}
		, DEPT		      	= ${DEPT}
		, POSITION		  	= ${POSITION}
		, EMAIL  		    = ${EMAIL}
		, PHONE           	= ${PHONE}
		, employee_no       = ${EMPLOYEE_NO}
		, DEL_FLAG        	= ${DEL_FLAG}
		, LANGUAGE			= 'KO'
		, USER_TYPE			= #DB_OWNER#nvl($S{USER_TYPE}, USER_TYPE)
WHERE
	  HOUSE_CODE        	= ${session.HOUSE_CODE}
  AND COMPANY_CODE 			= ${session.COMPANY_CODE}
  AND USER_ID           	= ${USER_ID}


INSERT INTO SUSMT
	(
		  HOUSE_CODE
		, USER_ID 
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, COMPANY_CODE
		, PLANT_CODE
		, USER_NAME_LOC
		, PASSWORD
		, DEPT
		, POSITION
		, EMAIL		
		, COUNTRY
		, SIGN_STATUS
		, WORK_TYPE
		, MENU_PROFILE_CODE
		, USER_TYPE
		, PASS_CHECK_CNT
		, PW_RESET_FLAG
		, DEL_FLAG
		, DATE_FORMAT
		, PHONE
		, LANGUAGE
		, EMPLOYEE_NO
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${USER_ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${session.COMPANY_CODE}
		, ${session.COMPANY_CODE}
		, ${USER_NAME_LOC}
		, ${PASSWORD}
		, ${DEPT}
		, ${POSITION}
		, ${EMAIL}				
		, ${COUNTRY}
		, ${SIGN_STATUS}
		, ${WORK_TYPE}
		, ${MENU_PROFILE_CODE}
		, ${USER_TYPE}
		, ${PASS_CHECK_CNT}
		, ${PW_RESET_FLAG}
		, ${DEL_FLAG}
		, '%Y/%m/%d'
		, ${PHONE}
		, ${LANGUAGE}
		, ${EMPLOYEE_NO}
	)


UPDATE SUSMT
	SET	DEL_FLAG = 'Y'
WHERE 
	HOUSE_CODE 		= ${session.HOUSE_CODE}
AND COMPANY_CODE 	= ${session.COMPANY_CODE}
AND USER_ID 		= ${USER_ID}
